#include <string>
#include <unordered_set>

class Solution {
public:
    bool hasAllCodes(std::string s, int k) {
        int needed = 1 << k;
        if ((int)s.size() < needed + k - 1) return false;
        std::unordered_set<std::string> seen;
        for (int i = 0; i <= (int)s.size() - k; ++i) {
            seen.insert(s.substr(i, k));
            if ((int)seen.size() == needed) return true;
        }
        return (int)seen.size() == needed;
    }
};

import java.util.*;

class Solution {
    public boolean hasAllCodes(String s, int k) {
        int needed = 1 << k;
        if (s.length() < needed + k - 1) return false;
        Set<String> seen = new HashSet<>();
        for (int i = 0; i <= s.length() - k; i++) {
            seen.add(s.substring(i, i + k));
            if (seen.size() == needed) return true;
        }
        return seen.size() == needed;
    }
}

var hasAllCodes = function(s, k) {
    const needed = 1 << k;
    if (s.length < needed + k - 1) return false;
    const seen = new Set();
    for (let i = 0; i <= s.length - k; i++) {
        seen.add(s.slice(i, i + k));
        if (seen.size === needed) return true;
    }
    return seen.size === needed;
};
